import { WaterfallChart, type WaterfallStep } from '@absoluteui/components/waterfall-chart';

const steps: WaterfallStep[] = [
  { id: 'open', label: 'Opening', kind: 'total', value: 100 },
  { id: 'sales', label: 'Sales', value: 40 },
  { id: 'refunds', label: 'Refunds', value: -15 },
  { id: 'other', label: 'Other', value: null },
  { id: 'close', label: 'Closing', kind: 'total' },
];
const host = document.createElement('div');
document.body.append(host);
WaterfallChart.create(host, {
  label: 'Profit bridge',
  steps,
  valueFormat: { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 },
  valueAxis: { label: 'EUR' },
});

import { WaterfallChart } from '@absoluteui/components/waterfall-chart';

const host = document.querySelector<HTMLElement>('#headcount');
if (host) {
  const chart = WaterfallChart.create(host, {
    label: 'Headcount',
    steps: [
      { id: 'start', label: 'Start', kind: 'total', value: 250 },
      { id: 'hires', label: 'Hires', value: 30 },
      { id: 'leavers', label: 'Leavers', value: -12 },
      { id: 'end', label: 'End', kind: 'total' },
    ],
    colors: { increase: 5, decrease: 6, total: 1 },
    connectors: false,
  });
  host.dataset.summary = chart.summary;
}
